// Shapes the API sends, from its OpenAPI schema (src/api/schema.d.ts, generated by
// `make web-types`). The WebSocket events wrap them; they aren't in OpenAPI, so they're here.
import type { components } from './schema'

type Schemas = components['schemas']
export type TurnResponse = Schemas['TurnResponse']
export type BookResult = Schemas['BookResult']
export type Availability = Schemas['Availability']
export type Chip = Schemas['Chip']
export type BookDetail = Schemas['BookDetail']
export type FeaturedBook = Schemas['FeaturedBook']
export type Reply = Schemas['Reply']
export type ReplyItem = Schemas['ReplyItem']
/** One checked part of a reply, streamed before the whole (socket only, not in OpenAPI). */
export interface ReplyPiece {
  kind: 'intro' | 'item' | 'follow_up'
  text: string
  work_id: number | null
  source: 'llm' | 'template'
}
export type Relaxation = Schemas['Relaxation']
export type Guess = Schemas['Guess']
export type GenreCount = Schemas['GenreCount']
export type Bench = Schemas['Bench']
export type SystemScore = Schemas['SystemScore']
/** The filters form; the socket message carries the same fields. */
export type Filters = Pick<Schemas['FiltersRequest'], 'pages_max' | 'year_from' | 'year_to' | 'available_now'>

/** Server -> client, per turn: "turn" (cards, chips, notes) as soon as retrieval is done,
 * then "reply" once the narration is written, then "done". */
export type ServerEvent =
  | ({ type: 'turn' } & TurnResponse)
  | { type: 'reply'; turn: number; reply: Reply }
  | ({ type: 'reply_piece'; turn: number } & ReplyPiece)
  | { type: 'done'; turn: number }
  | { type: 'cancelled'; turn: number }
  | { type: 'audio'; turn: number; seq: number; text: string; wav: string; ms: number }
  | { type: 'speak'; on: boolean }
  | { type: 'listening'; on: boolean; reason?: 'heard' | 'stopped' | 'no speech' | 'unavailable' }
  | { type: 'speech_start' }
  | { type: 'transcript'; text: string; fixed: { heard: string; catalog: string }[]; ms: number }
  | { type: 'error'; message: string }

export type ClientMessage =
  | { type: 'text'; text: string; limit?: number; narrate?: boolean }
  | { type: 'undo' }
  | { type: 'remove_chip'; field: string; label: string; narrate?: boolean }
  | { type: 'chip_strength'; field: string; label: string; strength: 'hard' | 'soft'; narrate?: boolean }
  | { type: 'more_like' | 'less_like'; work_id: number; narrate?: boolean }
  | { type: 'surprise'; narrate?: boolean }
  | { type: 'explore'; genre: string; narrate?: boolean }
  | ({ type: 'filters'; narrate?: boolean } & Filters)
  | { type: 'speak'; on: boolean }
  | { type: 'listen'; on: boolean }
  | { type: 'cancel' }
